create or replace function public.add_collaborator_email_alias(target_collaborator_id uuid,target_email text,target_is_primary boolean default false)
returns uuid language plpgsql security definer set search_path=public as $$ declare collaborator public.collaborators%rowtype; alias_id uuid; normalized_email text;
begin select * into collaborator from public.collaborators where id=target_collaborator_id for update; if collaborator.id is null or not public.has_organization_role(collaborator.organization_id,array['SUPER_ADMIN','ORG_ADMIN','MANAGER']::public.platform_role[]) then raise exception 'COLLABORATOR_ALIAS_NOT_AUTHORIZED'; end if; normalized_email:=lower(trim(target_email)); if position('@' in normalized_email)<=1 then raise exception 'COLLABORATOR_ALIAS_INVALID_EMAIL'; end if;
if target_is_primary then update public.collaborator_email_aliases set is_primary=false where collaborator_id=collaborator.id and active; end if;
insert into public.collaborator_email_aliases(organization_id,collaborator_id,email,is_primary) values(collaborator.organization_id,collaborator.id,normalized_email,target_is_primary) returning id into alias_id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(collaborator.organization_id,auth.uid(),'COLLABORATOR_EMAIL_ALIAS_ADDED','collaborator_email_alias',alias_id,jsonb_build_object('collaborator_id',collaborator.id,'is_primary',target_is_primary),'WEB'); return alias_id; end; $$;
create or replace function public.verify_collaborator_email_alias(target_alias_id uuid)
returns void language plpgsql security definer set search_path=public as $$ declare alias_record public.collaborator_email_aliases%rowtype;
begin select * into alias_record from public.collaborator_email_aliases where id=target_alias_id for update; if alias_record.id is null or not public.has_organization_role(alias_record.organization_id,array['SUPER_ADMIN','ORG_ADMIN']::public.platform_role[]) then raise exception 'COLLABORATOR_ALIAS_NOT_AUTHORIZED'; end if; if not alias_record.active then raise exception 'COLLABORATOR_ALIAS_INACTIVE'; end if;
update public.collaborator_email_aliases set verified_at=coalesce(verified_at,clock_timestamp()) where id=alias_record.id;
insert into public.audit_logs(organization_id,actor_id,action,entity_type,entity_id,after_value,source) values(alias_record.organization_id,auth.uid(),'COLLABORATOR_EMAIL_ALIAS_VERIFIED','collaborator_email_alias',alias_record.id,jsonb_build_object('collaborator_id',alias_record.collaborator_id),'WEB'); end; $$;
revoke all on function public.add_collaborator_email_alias(uuid,text,boolean),public.verify_collaborator_email_alias(uuid) from public; grant execute on function public.add_collaborator_email_alias(uuid,text,boolean),public.verify_collaborator_email_alias(uuid) to authenticated;
